abstract class DocumentRenderer {
    // Public template method orchestrating the workflow
    public final void renderDocument() {
        renderHeader();
        renderBody();
        renderFooter();
    }

    // Protected hooks meant to be customized by subclasses
    protected void renderHeader() {
        System.out.println("=== Default Header ===");
    }
    protected abstract void renderBody();
    protected void renderFooter() {
        System.out.println("=== Default Footer ===");
    }
}

class InvoiceRenderer extends DocumentRenderer {
    @Override
    protected void renderBody() {
        System.out.println("Invoice #1001: Total $249.99");
    }
}

public class TemplateMethodDemo {
    public static void main(String[] args) {
        DocumentRenderer renderer = new InvoiceRenderer();
        renderer.renderDocument();
    }
}

