practiceProblems.solution:
public class ProtectedChecker {
    public static boolean isLegalReferenceAccess(boolean inSubclass, boolean samePackage, boolean accessedThroughSubclassRef) {
        if (samePackage) return true;
        if (inSubclass && accessedThroughSubclassRef) return true;
        return false;
    }

    public static void main(String[] args) {
        System.out.println(isLegalReferenceAccess(false, true, false));
        System.out.println(isLegalReferenceAccess(true, false, false));
        System.out.println(isLegalReferenceAccess(true, false, true));
    }
}

