public class CloneOverrideDemo {
    static class Customer implements Cloneable {
        String name;
        public Customer(String n) { this.name = n; }

        @Override
        public Customer clone() throws CloneNotSupportedException {
            return (Customer) super.clone();
        }
    }

    public static void main(String[] args) throws Exception {
        Customer c1 = new Customer("Dana");
        Customer c2 = c1.clone();
        System.out.println("Cloned name: " + c2.name);
        System.out.println("Different references: " + (c1 != c2));
    }
}

