import java.util.*;

public class TransactionSubsystem {
    static class TransactionHandler {
        public final void process() {
            try {
                executeTask();
                onCommit();
            } catch (Exception e) {
                onRollback();
            }
        }
        protected void executeTask() { System.out.println("Task executed"); }
        protected void onCommit() { System.out.println("Committed"); }
        protected void onRollback() { System.out.println("Rolled back"); }
    }

    static class AuditHandler extends TransactionHandler {
        @Override
        protected void onCommit() {
            super.onCommit();
            System.out.println("Audit: Transaction successfully logged");
        }
    }

    public static void main(String[] args) {
        TransactionHandler handler = new AuditHandler();
        handler.process();
    }
}
